extends "res://htd/htd_test.gd"


func _run_tests() -> void:
	var runner := await instantiate_scene("res://test_runner.tscn")
	if not check("runner_loaded", runner != null, "La scena test_runner.tscn deve avviarsi ed eseguire tutti i controlli senza errori"):
		return
	check("has_boundaries", has_function(runner, "test_inventory_boundaries"), "test_runner.gd deve contenere la funzione test_inventory_boundaries()")
	check("has_invalid", has_function(runner, "test_inventory_invalid"), "test_runner.gd deve contenere la funzione test_inventory_invalid()")

	var code := source_of("res://test_runner.gd")
	var assert_count := count_in_code("res://test_runner.gd", "assert")
	check("assert_count", assert_count >= 12, "Lo script deve contenere tutte le asserzioni necessarie per coprire limiti ed errori (trovati: %d assert)" % assert_count)
	check("checks_capacity", code.contains("get_occupied_slots"), "I test sui limiti devono verificare il conteggio degli slot occupati")
	check("checks_negative", code.contains("remove_item") and code.contains("add_item"), "I test devono verificare il rifiuto di operazioni non valide sia in aggiunta che in rimozione")

extends "res://htd/htd_test.gd"


func _run_tests() -> void:
	var runner := await instantiate_scene("res://test_runner.tscn")
	if not check("runner_loaded", runner != null, "La scena test_runner.tscn deve avviarsi ed eseguire con successo tutti i controlli"):
		return
	check("has_room_normal", has_function(runner, "test_room_map_normal"), "test_runner.gd deve definire la funzione test_room_map_normal()")
	check("has_room_invalid", has_function(runner, "test_room_map_invalid"), "test_runner.gd deve definire la funzione test_room_map_invalid()")

	var code := source_of("res://test_runner.gd")
	check("uses_room_map", code.contains("RoomMap"), "I nuovi test devono istanziare e verificare la classe RoomMap")
	check("checks_navigation", code.contains("connect_rooms") and code.contains("move"), "I controlli devono verificare il collegamento tra stanze e il metodo move()")
	check("checks_exits", code.contains("get_destination") and code.contains("get_room_description"), "I controlli devono verificare get_destination() e get_room_description()")

	var assert_count := count_in_code("res://test_runner.gd", "assert")
	check("assert_count", assert_count >= 18, "Lo script deve contenere tutte le asserzioni richieste per inventario e mappa (trovati: %d assert)" % assert_count)
